contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // The test contract deployed c, so this contract is C's owner.
    function run(address receiver, uint256 amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= 0); // no precondition on params

        // record balance of c before the call
        uint256 before = address(c).balance;

        bool reverted;
        // try to invoke sendTo with provided parameters, capturing revert status
        c.sendTo(receiver, amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 afterBal = address(c).balance;

        // If call reverted, balances must be unchanged.
        // If call did not revert, amount must be > 0, receiver must be non-zero,
        // and c.balance must have decreased exactly by amount.
        assert(
            (reverted && afterBal == before)
            ||
            (!reverted && amount > 0 && receiver != address(0) && before == afterBal + amount)
        );
    }

    receive() external payable {}
}

